"""Reproducible comparison; expectations are versioned, never generated by the solution."""
from __future__ import annotations

import argparse
from contextlib import contextmanager
import csv
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import shutil
import statistics
import sys
import tempfile

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from src.data_access import get_request
from src.solution import analyze_request
from src.providers import live_configuration
from src.vendor_client import get_vendor_risk
from src.tools import DATA_DIR, csv_rows


@contextmanager
def case_inputs(case):
    request = get_request(case["request_id"])
    request.update(case.get("request_overrides", {}))
    # Different IDs ensure the policy cannot be a lookup table of public answers.
    request["request_id"] = "EVAL-" + case["case_id"]
    with tempfile.TemporaryDirectory(prefix="procurement-eval-") as temp:
        data_dir = Path(temp) / "data"
        shutil.copytree(DATA_DIR, data_dir)
        if "registry_override" in case:
            rows = csv_rows("vendors.csv", data_dir)
            for row in rows:
                if row["vendor_name"] == request["vendor_name"]:
                    row.update(case["registry_override"])
            with (data_dir / "vendors.csv").open("w", newline="", encoding="utf-8") as f:
                writer = csv.DictWriter(f, fieldnames=rows[0].keys())
                writer.writeheader(); writer.writerows(rows)

        def risk_fetcher(vendor):
            if case.get("simulate_timeout"):
                from requests import Timeout
                raise Timeout("Controlled transport failure")
            result = get_vendor_risk(vendor)
            result.update(case.get("risk_override", {}))
            return result

        yield request, data_dir, risk_fetcher


def grade(decision, case):
    failures = []
    correct = decision.action == case["expected_action"]
    if not correct: failures.append(f"action {decision.action}; expected {case['expected_action']}")
    policy = True
    for field, expected in [("required_approvals", case.get("approvals", [])), ("risk_flags", case.get("flags", []))]:
        for item in expected:
            if item not in getattr(decision, field):
                policy = False; failures.append(f"missing {field}: {item}")
    for field, forbidden in [("required_approvals", case.get("forbidden_approvals", [])), ("risk_flags", case.get("forbidden_flags", []))]:
        for item in forbidden:
            if item in getattr(decision, field):
                policy = False; failures.append(f"unexpected {field}: {item}")
    for token in case.get("missing_contains", []):
        if not any(token.casefold() in item.casefold() for item in decision.missing_information):
            policy = False; failures.append(f"missing-information item absent: {token}")
    if len(decision.missing_information) > case.get("max_missing", float("inf")):
        policy = False; failures.append("unexpected missing information")
    tel = decision.telemetry
    canonical = {e["evidence_id"]: e for trace in tel.tool_trace for e in trace.get("evidence", [])}
    grounded = bool(decision.evidence) and all(canonical.get(e.evidence_id) == e.model_dump() for e in decision.evidence)
    grounded = grounded and "ungrounded_model_output" not in decision.risk_flags
    if not grounded: failures.append("evidence not present unchanged in tool ledger, or unsupported model citation")
    human = decision.human_review_required and decision.review_status == "awaiting_human_review" and bool(decision.required_approvals) and bool(decision.next_step)
    if not human: failures.append("human handoff invalid")
    healthy_model = "model_unavailable" not in decision.risk_flags
    if not healthy_model: failures.append("live model did not complete")
    return {"recommendation_correct": correct, "policy_correct": policy, "grounded": grounded,
            "human_handoff_correct": human, "model_completed": healthy_model if tel.mode == "live" else None, "passed": not failures,
            "failures": failures}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--mode", choices=["offline", "live"], default="offline")
    parser.add_argument("--repeat", type=int, default=3)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    if args.repeat < 1: parser.error("--repeat must be positive")
    config = live_configuration() if args.mode == "live" else None
    if config is not None and not config.configured:
        parser.error(f"Live evaluation requires {config.key_variable} in the local .env. No offline substitution is made.")
    case_file = ROOT / "evals" / "cases.json"
    cases = json.loads(case_file.read_text())
    rows, decisions = [], []
    halted = False
    for repeat in range(args.repeat):
        for case in cases:
            for architecture in (("single", "staged") if repeat % 2 == 0 else ("staged", "single")):
                with case_inputs(case) as (request, data_dir, fetcher):
                    decision = analyze_request(request, architecture, args.mode, data_dir=data_dir, risk_fetcher=fetcher)
                checks = grade(decision, case)
                tel = decision.telemetry
                rows.append({"case_id":case["case_id"], "title":case["title"], "repeat":repeat+1,
                             "architecture":architecture, "mode":args.mode, **{k:v for k,v in checks.items() if k!="failures"},
                             "action":decision.action, "latency_ms":tel.latency_ms, "llm_calls":tel.llm_calls,
                             "tool_calls":tel.tool_calls, "input_tokens":tel.input_tokens, "output_tokens":tel.output_tokens,
                             "failures":" | ".join(checks["failures"])})
                decisions.append({"case_id":case["case_id"], "repeat":repeat+1, "request":request, "decision":decision.model_dump()})
                if not checks["passed"]: print("FAIL", architecture, case["case_id"], checks["failures"])
                if args.mode == "live":
                    print(f"{len(rows)}/{len(cases)*args.repeat*2}: {architecture} {case['case_id']} ({tel.llm_calls} model calls)", flush=True)
                if "model_rate_limited" in decision.risk_flags:
                    halted = True
                    print("Provider quota reached. Stopping model calls and saving partial results; this is not a complete architecture comparison.", flush=True)
                    break
            if halted: break
        if halted: break
    summaries = {}
    for architecture in ("single", "staged"):
        subset = [row for row in rows if row["architecture"]==architecture]
        summaries[architecture] = {"runs":len(subset), "planned_runs":len(cases)*args.repeat,
            "cases":len({row["case_id"] for row in subset}), "passed":sum(row["passed"] for row in subset),
            **{key+"_rate":sum(row[key] for row in subset)/len(subset) if subset else None for key in ("recommendation_correct", "policy_correct", "grounded", "human_handoff_correct")},
            "model_completed_rate": None if args.mode == "offline" or not subset else sum(row["model_completed"] for row in subset)/len(subset),
            "mean_latency_ms":round(statistics.mean(row["latency_ms"] for row in subset),3) if subset else None,
            "median_latency_ms":round(statistics.median(row["latency_ms"] for row in subset),3) if subset else None,
            "mean_llm_calls":statistics.mean(row["llm_calls"] for row in subset) if subset else None,
            "mean_tool_calls":statistics.mean(row["tool_calls"] for row in subset) if subset else None,
            "input_tokens":sum(row["input_tokens"] for row in subset), "output_tokens":sum(row["output_tokens"] for row in subset)}
    summary = {"mode":args.mode, "provider":config.provider if config else "none",
        "model":config.model if config else None,
        "comparison_complete":not halted, "halt_reason":"provider_rate_limit" if halted else None,
        "gemini_min_interval_seconds":float(os.getenv("GEMINI_MIN_INTERVAL_SECONDS", "6")) if config and config.provider=="gemini" else None,
        "measured_at":datetime.now(timezone.utc).isoformat(), "python":sys.version.split()[0],
        "repeat":args.repeat, "case_set_sha256":hashlib.sha256(case_file.read_bytes()).hexdigest(),
        "conditions":"Local HTTP mock; paired alternating architecture order; date/conflict cases override fetched responses and copied registry records; timeout is controlled.",
        "limitations":("Offline simulation does not measure LLM reasoning, prompt-injection robustness of a live model, or production latency. " if args.mode=="offline" else "Prototype latency includes configured provider pacing; this is not a production-load measurement. ") + "Grounding is exact ledger provenance, not an independent semantic entailment judgment. Partial results cannot establish an architecture comparison.",
        "architectures":summaries}
    out = args.output or ROOT/"evals"/"results"/args.mode
    out.mkdir(parents=True,exist_ok=True)
    (out/"summary.json").write_text(json.dumps(summary,indent=2)+"\n")
    (out/"decisions.json").write_text(json.dumps(decisions,indent=2)+"\n")
    with (out/"runs.csv").open("w",newline="") as f:
        writer=csv.DictWriter(f,fieldnames=rows[0].keys());writer.writeheader();writer.writerows(rows)
    print(json.dumps(summary,indent=2))
    print("Results:",out)
    if any(not row["passed"] for row in rows): raise SystemExit(1)


if __name__=="__main__": main()
